<?php
require __DIR__.'/app/bootstrap.php';
if(!is_file(__DIR__.'/.installed')){header('Location: setup.php');exit;}
try {db();$currentUser=user();}catch(Throwable $ex){error_log($ex->getMessage());http_response_code(503);exit('FORME cannot connect to the database. Start MySQL in XAMPP and check config.local.php.');}
$page=(string)($_GET['page']??'home');
$allowed=['home','catalog','product','login','register','account','wishlist','cart','checkout','orders','order','about','help','admin'];
if(!in_array($page,$allowed,true)){$page='404';http_response_code(404);}
if(in_array($page,['account','wishlist','cart','checkout','orders','order'],true))$currentUser=login_required();
if($page==='admin')$currentUser=admin_required();
require __DIR__.'/app/actions.php';
$old=$_SESSION['old']??[];unset($_SESSION['old']);
function old(string $name,$default=''): string {global $old;return e($old[$name]??$default);}
$cartCount=$currentUser?(int)(one('SELECT COALESCE(SUM(quantity),0) n FROM cart_items WHERE user_id=?',[$currentUser['id']])['n']??0):0;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="FORME — considered everyday wear for women, men and little ones."><title>FORME · <?=e(ucfirst($page))?></title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head><body class="page-<?=e($page)?>">
<a class="skip-link" href="#main">Skip to content</a>
<?php if($page!=='admin'):?>
<header class="site-header <?=$page==='home'?'overlay':''?>"><a class="wordmark" href="<?=e(url())?>"><?php if(setting('logo')):?><img class="brand-logo" src="<?=e(safe_image(setting('logo')))?>" alt="<?=e(setting('brand_name','FORME'))?>"><?php else:?><?=e(setting('brand_name','FORME'))?><span><?=e(setting('tagline','CONSIDERED EVERYDAY WEAR'))?></span><?php endif;?></a><button class="menu-toggle icon-button" aria-label="Open navigation" aria-expanded="false">☰</button><nav class="main-nav" aria-label="Main navigation"><?php foreach(['Women','Men','Kids'] as $department):?><a href="<?=e(url('catalog',['department'=>$department]))?>"><?=e($department)?></a><?php endforeach;?><a href="<?=e(url('catalog',['sort'=>'new']))?>">New In</a><a href="<?=e(url('about'))?>">Our Story</a></nav><div class="header-tools"><a href="<?=e(url('catalog',['search'=>'']))?>" aria-label="Search" title="Search"><?=icon('search')?></a><a href="<?=e(url('wishlist'))?>" aria-label="Wishlist" title="Wishlist"><?=icon('heart')?></a><a href="<?=e(url($currentUser?'account':'login'))?>" class="account-link"><?=$currentUser?'Account':'Sign in'?></a><a href="<?=e(url('cart'))?>" class="bag-link" aria-label="Shopping bag, <?=$cartCount?> items"><?=icon('bag')?> <span><?=$cartCount?></span></a></div></header>
<?php endif;?>
<?php if(isset($_SESSION['flash'])):[$msg,$type]=$_SESSION['flash'];unset($_SESSION['flash']);?><div class="notice toast <?=e($type)?>" role="status"><?=e($msg)?><button type="button" aria-label="Dismiss notification" data-dismiss>×</button></div><?php endif;?>
<main id="main"><?php
try{if($page==='admin')require __DIR__.'/app/admin.php';elseif($page==='home')require __DIR__.'/app/home.php';elseif(in_array($page,['catalog','product'],true))require __DIR__.'/app/catalog.php';elseif(in_array($page,['cart','checkout','orders','order','wishlist'],true))require __DIR__.'/app/shop.php';else require __DIR__.'/app/account.php';}
catch(Throwable $ex){error_log($ex->getMessage());http_response_code(500);echo '<section class="container empty-state"><h1>Something needs attention.</h1><p>Please try again. If this continues, check the PHP error log.</p><a href="index.php" class="btn">Back to the store</a></section>';}
?></main>
